async function main() {
  const rows = QUESTIONS.map(q => ({
    question_text: q.question_text,
    option_a: q.option_a,
    option_b: q.option_b,
    option_c: q.option_c,
    option_d: '',
    correct_answer: q.correct_answer,
    category: q.category,
    difficulty: 'medium',
    explanation: q.explanation,
    reference: q.reference,
    exam_type: 'ppl',
    validation_status: 'pending',
  }))

  const { data, error } = await supabase.from('questions').insert(rows).select('id')
  if (error) throw new Error('Insert failed: ' + error.message)
  console.log(`Inserted ${data.length} figure-grounded questions (status=pending, awaiting admin review).`)
  console.log(`By category: Aerodynamics=8 (Figure 2), Aircraft Performance=8 (Figure 8), Airspace=9 (Legend 1)`)
}

main().catch(err => { console.error(err); process.exit(1) })
